const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeExternalUrl=value=>{const raw=String(value||'').trim();if(!raw)return '';try{const url=new URL(/^[a-z][a-z\d+.-]*:/i.test(raw)?raw:`https://${raw}`);return ['http:','https:'].includes(url.protocol)?url.href:''}catch{return ''}};
function readUiPreferences(){try{return JSON.parse(localStorage.getItem(`montajes-pc-ui-${profile?.id||'anon'}`)||'{}')}catch{return {}}}
function saveUiPreferences(){if(!profile||previewUserId)return;try{localStorage.setItem(`montajes-pc-ui-${profile.id}`,JSON.stringify({page:currentPage,catalogFilters,expandedBuildIds:[...expandedBuildIds]}))}catch{}}
function canManage(){return isAdmin&&!previewUserId}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2400)}
function loginEmail(username){const clean=username.trim().toLowerCase().replace(/[^a-z0-9._+-]/g,'');return clean.includes('@')?clean:`${clean}@${AUTH_EMAIL_DOMAIN}`}

if(!supabaseClient){$('#login-error').textContent='No se pudo cargar Supabase. Comprueba tu conexión a Internet y vuelve a abrir la página.'}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const errorBox=$('#login-error');errorBox.textContent='';const submitButton=e.currentTarget.querySelector('button[type="submit"]');submitButton.disabled=true;submitButton.textContent='Iniciando sesión…';try{if(!supabaseClient)throw new Error('No se pudo cargar Supabase. Comprueba tu conexión a Internet.');const username=$('#username').value.trim();if(!username)throw new Error('Escribe tu usuario.');const {data,error}=await supabaseClient.auth.signInWithPassword({email:loginEmail(username),password:$('#password').value});if(error){errorBox.textContent=/invalid|credentials|user not found/i.test(error.message)?'Usuario o contraseña incorrectos':error.message;return}session=data.session;await startApp()}catch(error){errorBox.textContent=error?.message||'No se pudo iniciar sesión. Comprueba tu conexión y vuelve a intentarlo.'}finally{submitButton.disabled=false;submitButton.textContent='Iniciar sesión'}});
$('#sign-out').addEventListener('click',()=>supabaseClient.auth.signOut());
supabaseClient?.auth.onAuthStateChange((_event,newSession)=>{session=newSession;if(!session)showLogin()});
async function startApp(){if(!session)return;const {data,error}=await supabaseClient.from('profiles').select('id,username').eq('id',session.user.id).single();if(error){$('#login-error').textContent=error.code==='PGRST116'?'La cuenta inició sesión, pero aún no tiene perfil. Ejecuta el bloque de sincronización de perfiles del SQL de configuración.':'No se pudo leer el perfil desde Supabase. Revisa las políticas RLS y la tabla profiles.';await supabaseClient.auth.signOut();return}profile=data;isAdmin=profile.username.toLowerCase()==='nicknamed';previewUserId=null;previewUsername='';$('#user-preview-controls').classList.toggle('hidden',!isAdmin);$('#user-preview-menu').classList.add('hidden');$('#user-preview-toggle').classList.remove('active');$('#user-preview-toggle').setAttribute('aria-pressed','false');$('#user-preview-toggle').setAttribute('aria-expanded','false');const saved=readUiPreferences();catalogFilters={cpu:{brand:'Todas',sort:'date',query:'',...saved.catalogFilters?.cpu},gpu:{brand:'Todas',sort:'date',query:'',...saved.catalogFilters?.gpu}};for(const kind of ['cpu','gpu'])if(!['date','generation'].includes(catalogFilters[kind].sort))catalogFilters[kind].sort='date';expandedBuildIds=new Set(saved.expandedBuildIds||[]);currentPage=isAdmin&&['builds','catalog','admin'].includes(saved.page)?saved.page:'builds';document.title=isAdmin?'Montajes PC':'Visor de montajes';$('#login-screen').classList.add('hidden');$('#app').classList.remove('hidden');$('#signed-in-as').textContent=profile.username;$('#role-badge').textContent=isAdmin?'ADMINISTRADOR':'VISOR';renderNavigation();await Promise.all([loadCatalogUpdates(),loadReviewAlerts()]);await showPage(currentPage)}
function showLogin(){$('#app').classList.add('hidden');$('#login-screen').classList.remove('hidden');$('#password').value=''}
function mobileDrawer(){return window.matchMedia('(max-width: 760px)').matches}
function setDrawerOpen(open){const sidebar=$('#app-sidebar'),backdrop=$('#drawer-backdrop'),button=$('#menu-open');document.body.classList.toggle('drawer-open',open&&mobileDrawer());sidebar.classList.toggle('is-open',open&&mobileDrawer());backdrop.classList.toggle('is-visible',open&&mobileDrawer());sidebar.setAttribute('aria-hidden',String(mobileDrawer()&&!open));button.setAttribute('aria-expanded',String(open&&mobileDrawer()));if(!open)button.focus({preventScroll:true})}
function renderNavigation(){const items=previewUserId||!isAdmin?[['builds','Visor de montajes']]:[['builds','Montajes'],['catalog','Catálogo piezas'],['admin','Panel de admin']];$('#navigation').innerHTML=items.map(([id,title])=>`<button class="nav-button ${currentPage===id?'active':''}" data-page="${id}">${title}</button>`).join('');$$('.nav-button').forEach(b=>b.onclick=()=>{showPage(b.dataset.page);setDrawerOpen(false)});setDrawerOpen(false)}
$('#menu-open').addEventListener('click',()=>setDrawerOpen(true));$('#menu-close').addEventListener('click',()=>setDrawerOpen(false));$('#drawer-backdrop').addEventListener('click',()=>setDrawerOpen(false));window.addEventListener('keydown',event=>{if(event.key==='Escape')setDrawerOpen(false)});window.matchMedia('(max-width: 760px)').addEventListener('change',()=>setDrawerOpen(false));
let drawerTouch=null;document.addEventListener('touchstart',event=>{if(!mobileDrawer())return;const touch=event.changedTouches[0],sidebar=$('#app-sidebar'),open=document.body.classList.contains('drawer-open');drawerTouch={x:touch.clientX,y:touch.clientY,open,inside:sidebar.contains(event.target)||$('#drawer-backdrop').contains(event.target)}},{passive:true});document.addEventListener('touchend',event=>{if(!drawerTouch||!mobileDrawer())return;const touch=event.changedTouches[0],dx=touch.clientX-drawerTouch.x,dy=Math.abs(touch.clientY-drawerTouch.y),{x,open,inside}=drawerTouch;drawerTouch=null;if(dy>100)return;if(!open&&x<28&&dx>75)setDrawerOpen(true);else if(open&&inside&&dx< -75)setDrawerOpen(false)},{passive:true});
async function showPage(page){if((previewUserId||!isAdmin)&&page!=='builds')page='builds';currentPage=page;saveUiPreferences();renderNavigation();const viewerMode=!!previewUserId||!isAdmin;$('#page-title').textContent=page==='catalog'?'Catálogo piezas':page==='admin'?'Panel de admin':viewerMode?'Visor de montajes':'Montajes';$('#page-kicker').textContent=page==='catalog'?'COMPONENTES':page==='admin'?'GESTIÓN DE ACCESOS':previewUserId?'VISTA PREVIA':'TU ESPACIO';$$('.page').forEach(el=>el.classList.add('hidden'));$(`#${page}-page`).classList.remove('hidden');if(page==='catalog')renderCatalog();if(page==='builds')await loadBuilds();if(page==='admin')await loadAccessPanel()}

async function openUserPreviewMenu(){const menu=$('#user-preview-menu'),button=$('#user-preview-toggle');if(previewUserId){previewUserId=null;previewUsername='';$('#signed-in-as').textContent=profile.username;$('#role-badge').textContent='ADMINISTRADOR';document.title='Montajes PC';button.classList.remove('active');button.setAttribute('aria-pressed','false');button.setAttribute('aria-expanded','false');menu.classList.add('hidden');await showPage(pageBeforePreview);return}if(!menu.classList.contains('hidden')){menu.classList.add('hidden');button.setAttribute('aria-expanded','false');return}menu.classList.remove('hidden');button.setAttribute('aria-expanded','true');const status=$('#user-preview-status'),select=$('#user-preview-select');status.textContent='Cargando usuarios…';const {data,error}=await supabaseClient.from('profiles').select('id,username').order('username');if(error){status.textContent='No se pudieron cargar los usuarios.';return}previewProfiles=(data||[]).filter(user=>user.id!==session.user.id);select.innerHTML='<option value="">Selecciona un usuario…</option>'+previewProfiles.map(user=>`<option value="${esc(user.id)}">${esc(user.username)}</option>`).join('');status.textContent=previewProfiles.length?'Al elegir un usuario se mostrará solo lo que tiene permitido ver.':'No hay otros usuarios registrados.'}
$('#user-preview-toggle').addEventListener('click',openUserPreviewMenu);
$('#user-preview-select').addEventListener('change',async event=>{const selected=previewProfiles.find(user=>user.id===event.currentTarget.value);if(!selected)return;pageBeforePreview=currentPage;previewUserId=selected.id;previewUsername=selected.username;$('#user-preview-menu').classList.add('hidden');$('#user-preview-toggle').setAttribute('aria-expanded','false');$('#user-preview-toggle').setAttribute('aria-pressed','true');$('#user-preview-toggle').classList.add('active');$('#signed-in-as').textContent=`Vista de ${previewUsername}`;$('#role-badge').textContent='VISTA PREVIA';document.title='Visor de montajes';await showPage('builds')});

const generationCollator=new Intl.Collator('es',{numeric:true,sensitivity:'base'});
function compareCatalogGeneration(a,b){const generationOrder=generationCollator.compare(b.generation,a.generation);if(generationOrder)return generationOrder;const modelNumber=item=>Number(item.name.match(/\d{3,}/)?.[0]||0);const modelOrder=modelNumber(b)-modelNumber(a);if(modelOrder)return modelOrder;const nameOrder=generationCollator.compare(b.name,a.name);return nameOrder||b.date.localeCompare(a.date)}
async function loadCatalogUpdates(){try{const response=await fetch(`catalog-updates.json?v=${Date.now()}`,{cache:'no-store'});if(!response.ok)return;const payload=await response.json();catalogUpdates=Array.isArray(payload.products)?payload.products:[];const updated=payload.updatedAt?new Date(payload.updatedAt).toLocaleDateString('es-ES'):'—';$('#catalog-updated').textContent=`Comprobado a diario · Última actualización: ${updated}`}catch{catalogUpdates=[];$('#catalog-updated').textContent='Catálogo base disponible; la actualización diaria requiere conexión web.'}}
async function loadReviewAlerts(){try{const response=await fetch(`review-alerts.json?v=${Date.now()}`,{cache:'no-store'});if(!response.ok)return;const payload=await response.json();reviewAlerts=Array.isArray(payload.alerts)?payload.alerts:[];const checked=payload.checkedAt?new Date(payload.checkedAt).toLocaleString('es-ES'):'—';$('#reviews-updated').textContent=`Reviews y reportes de fallos comprobados a diario · Última revisión: ${checked}`}catch{reviewAlerts=[];$('#reviews-updated').textContent='Las advertencias recientes requieren conexión web.'}}
function catalogItems(){const key=item=>`${item.kind}|${item.brand}|${item.name}`;const items=new Map(CATALOG.map(item=>[key(item),item]));for(const item of catalogUpdates)items.set(key(item),{...items.get(key(item)),...item});return [...items.values()]}
function isComingSoon(item){const release=item.releaseDate||item.date;if(release&&release!=='unknown'&&!Number.isNaN(Date.parse(`${release}T23:59:59`)))return Date.parse(`${release}T23:59:59`)>Date.now();return item.status==='announced'||item.status==='coming-soon'}
function catalogDateLabel(item,options={year:'numeric',month:'long',day:'numeric'}){if(item.releaseDateLabel)return item.releaseDateLabel;const date=item.releaseDate||item.date;if(!date)return '';const parsed=new Date(`${date}T12:00:00`);return Number.isNaN(parsed.getTime())?String(date):parsed.toLocaleDateString('es-ES',options)}
function catalogItemKey(item){return `${item.kind}|${item.brand}|${item.name}`}
function updateCompareControls(){const button=$('#compare-toggle'),status=$('#compare-status'),show=$('#compare-show'),kind=compareSelection[0]?.kind;button.classList.toggle('active',compareMode);button.setAttribute('aria-pressed',String(compareMode));button.textContent=compareMode?'Cancelar comparación':'Comparar';status.classList.toggle('hidden',!compareMode);status.textContent=compareMode?`Selecciona de 2 a 5 ${kind==='cpu'?'CPU':kind==='gpu'?'GPU':'piezas'} (${compareSelection.length}/5)`:'';show.classList.toggle('hidden',!compareMode||compareSelection.length<2);show.disabled=compareSelection.length<2||compareSelection.length>5;show.textContent=`Ver comparación (${compareSelection.length})`}
function toggleCompareItem(item){const key=catalogItemKey(item),existing=compareSelection.findIndex(selected=>catalogItemKey(selected)===key);if(existing>=0){compareSelection.splice(existing,1)}else if(compareSelection.length&&compareSelection[0].kind!==item.kind){toast(`Solo puedes comparar ${compareSelection[0].kind==='cpu'?'CPUs con CPUs':'GPUs con GPUs'}.`);return}else if(compareSelection.length<5){compareSelection.push(item)}else{toast('Has llegado al máximo de 5 piezas. Quita una para elegir otra.');return}renderCatalog()}
function comparisonNumber(value){const match=String(value??'').trim().match(/-?\d[\d.,]*/);if(!match)return null;let number=match[0];if(number.includes(',')&&number.includes('.'))number=number.replace(/\./g,'').replace(',','.');else if(number.includes(','))number=number.replace(',','.');else if(/\.\d{3}$/.test(number))number=number.replace(/\./g,'');const parsed=Number(number);return Number.isFinite(parsed)?parsed:null}
function comparisonRanks(key,items,specs){if(['Marca','Tipo','Generación','Arquitectura','Socket'].includes(key))return items.map(()=> '');let values;if(key==='Lanzamiento'){values=items.map(item=>{const date=item.releaseDate||item.date;return !item.releaseDateLabel&&/^\d{4}-\d{2}-\d{2}$/.test(String(date||''))?Date.parse(`${date}T12:00:00`):null})}else if(key==='Memoria'&&specs.some(row=>row[key])&&!specs.filter(row=>row[key]).every(row=>/\bGB\b/i.test(row[key]))){return items.map(()=> '')}else{values=specs.map(row=>comparisonNumber(row[key]))}const valid=values.filter(value=>value!==null);if(valid.length<2)return values.map(()=> '');const lowerIsBetter=/tdp|tbp|consumo|potencia|psu|fuente recomendada|watts?/i.test(key),ordered=[...new Set(valid)].sort((a,b)=>lowerIsBetter?a-b:b-a),best=ordered[0],second=ordered.find(value=>value!==best);return values.map(value=>value===null?'':value===best?'comparison-best':second!==undefined&&value===second?'comparison-second':'')}
function showComparison(items){const details=item=>({'Marca':item.brand,'Tipo':item.kind==='cpu'?'CPU':'GPU','Generación':item.generation||'—','Lanzamiento':catalogDateLabel(item)||'—',...(item.specs||{})});const specs=items.map(details),keys=[...new Set(specs.flatMap(item=>Object.keys(item)))];$('#comparison-content').innerHTML=`<p class="comparison-legend"><span><u>Mejor valor</u></span><span><strong>Segundo mejor</strong></span></p><div class="comparison-table-wrap"><table class="comparison-table"><thead><tr><th>Especificación</th>${items.map(item=>`<th>${esc(item.name)}</th>`).join('')}</tr></thead><tbody>${keys.map(key=>{const ranks=comparisonRanks(key,items,specs);return `<tr><th scope="row">${esc(key)}</th>${specs.map((row,index)=>`<td class="${ranks[index]}">${esc(row[key]??'—')}</td>`).join('')}</tr>`}).join('')}</tbody></table></div>`;$('#comparison-dialog').showModal()}
$('#compare-toggle').addEventListener('click',()=>{compareMode=!compareMode;compareSelection=[];renderCatalog()});
$('#compare-show').addEventListener('click',()=>{if(compareSelection.length>=2&&compareSelection.length<=5)showComparison(compareSelection)});
$('#close-comparison-dialog').addEventListener('click',()=>$('#comparison-dialog').close());
$('#comparison-dialog').addEventListener('close',()=>{compareSelection=[];renderCatalog()});
function renderCatalog(){const kindLabels={cpu:'PROCESADOR',gpu:'TARJETA GRÁFICA'};for(const kind of ['cpu','gpu']){const state=catalogFilters[kind];const brandRoot=document.querySelector(`[data-brand-filter="${kind}"]`);brandRoot.innerHTML=BRANDS.map(brand=>`<button class="filter-pill ${state.brand===brand?'active':''}" type="button" data-brand="${brand}" aria-pressed="${state.brand===brand}">${brand}</button>`).join('');brandRoot.querySelectorAll('.filter-pill').forEach(button=>button.onclick=()=>{state.brand=button.dataset.brand;saveUiPreferences();renderCatalog()});const sortSelect=document.querySelector(`[data-catalog-sort="${kind}"]`);sortSelect.value=state.sort;sortSelect.onchange=()=>{state.sort=sortSelect.value;saveUiPreferences();renderCatalog()};const searchInput=document.querySelector(`[data-catalog-search="${kind}"]`);searchInput.value=state.query;searchInput.oninput=()=>{state.query=searchInput.value;saveUiPreferences();renderCatalog();requestAnimationFrame(()=>document.querySelector(`#${kind}-catalog-list .component-card`)?.scrollIntoView({behavior:'smooth',block:'nearest'}))};const query=state.query.trim().toLocaleLowerCase('es');const items=catalogItems().filter(item=>item.kind===kind&&(state.brand==='Todas'||item.brand===state.brand)&&(!query||item.name.toLocaleLowerCase('es').includes(query))).sort((a,b)=>{const soon=Number(isComingSoon(b))-Number(isComingSoon(a));if(soon)return soon;return state.sort==='date'?String(b.date||'').localeCompare(String(a.date||'')):compareCatalogGeneration(a,b)});document.querySelector(`#${kind}-count`).textContent=`${items.length} modelos`;const list=document.querySelector(`#${kind}-catalog-list`);list.innerHTML=items.map(item=>{const soon=isComingSoon(item),date=item.releaseDate||item.date,selected=compareSelection.some(chosen=>catalogItemKey(chosen)===catalogItemKey(item));return `<button class="component-card ${soon?'coming-soon':''} ${compareMode&&selected?'comparison-selected':''}" type="button" aria-pressed="${compareMode&&selected}">${compareMode?`<span class="compare-pick">${selected?'✓ Seleccionada':'＋ Seleccionar'}</span>`:''}<div class="card-top"><span class="brand-tag">${esc(item.brand)}</span><span class="generation-tag">${esc(item.generation||'Nueva generación')}${soon?'<span class="coming-soon-tag">COMING SOON</span>':''}</span></div><h3>${esc(item.name)}</h3><p>${kindLabels[item.kind]} · ${soon?'Salida pendiente':'Lanzamiento'}${date?` · ${esc(catalogDateLabel(item,{year:'numeric',month:'short'}))}`:''}</p></button>`}).join('')||'<p class="muted">No hay piezas con este filtro.</p>';list.querySelectorAll('.component-card').forEach((card,index)=>card.onclick=()=>compareMode?toggleCompareItem(items[index]):showSpecs(items[index]))}updateCompareControls()}
const REVIEW_GUIDES={
 'Ryzen 9000':'En las reviews, los X3D destacan sobre todo en juegos; compara su sobreprecio con un Ryzen normal y con la generación anterior. En los modelos Ryzen 9, revisa también el rendimiento de productividad que realmente necesitas.',
 'Ryzen 8000G':'Las reviews valoran su gráfica integrada para equipos sin GPU dedicada. Ten en cuenta que el rendimiento depende mucho de la memoria rápida en doble canal y que no equivale a una tarjeta gráfica dedicada.',
 'Ryzen 7000':'Los Ryzen X3D suelen ser los más atractivos para jugar; los modelos normales ofrecen más equilibrio en productividad. AM5 requiere DDR5 y la temperatura alta bajo carga puede ser normal según el límite de boost.',
 'Ryzen 5000':'La plataforma AM4 y DDR4 puede abaratar una actualización, pero comprueba BIOS y compatibilidad exacta de la placa. Para juegos, la caché X3D puede cambiar mucho el resultado frente a modelos normales.',
 'Ryzen 3000':'Suelen seguir siendo útiles en equipos AM4 económicos. Las reviews actuales recomiendan valorar el coste de la plataforma completa y no solo el precio del procesador; confirma soporte BIOS y límites de memoria.',
 'Ryzen 2000':'Es una plataforma antigua: verifica compatibilidad de placa, BIOS y memoria, y compara el coste usado con un equipo más reciente. El rendimiento por núcleo y la eficiencia quedan por detrás de generaciones actuales.',
 'Core Ultra 200S':'Las reviews destacan productividad y eficiencia, pero el rendimiento en juegos varía bastante por modelo y configuración. Compara resultados reales con Core de 14.ª generación y Ryzen X3D antes de elegir.',
 '14.ª generación':'En reviews y reportes de usuarios se han documentado problemas de estabilidad en algunos Core de 13.ª/14.ª generación. Instala BIOS y microcódigo recientes, usa límites de potencia recomendados y comprueba la política de garantía.',
 'Core 9.ª generación':'Son procesadores antiguos: comprueba el precio de segunda mano, consumo, compatibilidad de placa y ausencia de funciones recientes. Un modelo de gama alta de esta época no siempre supera a un CPU moderno de gama media.',
 'Core 8.ª generación':'La plataforma ya es antigua; revisa coste y compatibilidad de placa antes de reutilizarla. En juegos modernos importan también los hilos disponibles y el rendimiento por núcleo.',
 'GeForce RTX 50':'Los análisis separan rendimiento nativo de generación de fotogramas: DLSS puede aumentar la fluidez percibida, pero no sustituye el rendimiento base ni reduce la latencia por sí solo. Comprueba VRAM y consumo del modelo concreto.',
 'GeForce RTX 40':'Las reviews suelen destacar buena eficiencia y DLSS 3. Compara el precio con la tarjeta equivalente de la generación nueva y fíjate en la VRAM, especialmente en modelos de 8 o 12 GB para juegos exigentes.',
 'GeForce RTX 30':'Compara rendimiento rasterizado, consumo y memoria disponible; algunas variantes de 8 GB pueden limitar texturas de alta resolución. En segunda mano, comprueba temperaturas, estado y uso previo.',
 'GeForce RTX 20':'Fue la primera generación GeForce RTX, pero el trazado de rayos puede resultar costoso en estos modelos. Para segunda mano, compara el rendimiento sin RT y el precio frente a GPUs más recientes.',
 'GeForce GTX 10':'No incluye aceleración RT ni Tensor de RTX. Las reviews actuales la sitúan como opción de bajo coste para juegos menos exigentes; verifica soporte de drivers y precio de segunda mano.',
 'GeForce GTX 16':'No ofrece núcleos RT/Tensor ni DLSS. Valora el rendimiento rasterizado y el precio frente a modelos RTX o Radeon actuales; la VRAM de cada variante es importante.',
 'Radeon RX 9000':'Compara rendimiento rasterizado, trazado de rayos y precio real entre modelos. La VRAM y las funciones FSR pueden cambiar la experiencia; separa resultados nativos de escalado/generación de fotogramas.',
 'Radeon RX 7000':'Las reviews suelen valorar rasterizado y capacidad de memoria. El rendimiento de ray tracing y el consumo pueden diferir de alternativas Nvidia; compara juegos y resolución que usas.',
 'Radeon RX 6000':'Puede ofrecer buen rendimiento rasterizado, sobre todo si el precio usado es bajo. Revisa el resultado con ray tracing, el consumo y la cantidad de VRAM de la variante exacta.',
 'Arc Battlemage B-series':'Las reviews destacan la relación rendimiento/memoria en gamas económicas, aunque los resultados dependen del juego y de drivers. ReBAR/Resizable BAR es importante; comprueba compatibilidad de la plataforma.',
 'Arc Alchemist A-series':'El rendimiento y la compatibilidad mejoraron con drivers, pero pueden variar por juego y API. ReBAR es importante y conviene comprobar benchmarks de los títulos concretos que utilizas.'
};
function reviewGuide(item){const summary=item.reviewNote||REVIEW_GUIDES[item.generation]||(item.kind==='cpu'?'Compara benchmarks de juegos y productividad, consumo bajo carga, compatibilidad de socket/BIOS y coste de memoria antes de decidir.':'Compara benchmarks a la resolución que usarás, VRAM, consumo, temperatura, ruido y rendimiento con y sin escalado.');const context=item.kind==='cpu'?'Al contrastar opiniones de usuarios, comprueba la placa, BIOS, refrigeración y límites de potencia usados.':'Al contrastar opiniones de usuarios, comprueba el ensamblador exacto, BIOS/drivers, temperaturas y juegos probados.';return `${summary} ${context}`}
function alertsForItem(item){const norm=value=>String(value||'').toLocaleLowerCase('es').replace(/[^a-z0-9]+/g,' ').trim();const target=norm(item.name);return reviewAlerts.filter(alert=>alert.kind===item.kind&&norm(alert.model)===target)}
const GPU_PSU_REFERENCE={
 'GeForce RTX 5090':1000,'GeForce RTX 5080':850,'GeForce RTX 5070 Ti':750,'GeForce RTX 5070':650,'GeForce RTX 5060 Ti 16 GB':600,'GeForce RTX 5060 Ti 8 GB':600,'GeForce RTX 5060':550,'GeForce RTX 5050':550,
 'GeForce RTX 4090':850,'GeForce RTX 4080 SUPER':750,'GeForce RTX 4070 Ti SUPER':700,'GeForce RTX 4070 SUPER':650,'GeForce RTX 4060 Ti 16 GB':550,'GeForce RTX 4060 Ti 8 GB':550,'GeForce RTX 4060':550,
 'GeForce RTX 3090 Ti':850,'GeForce RTX 3090':750,'GeForce RTX 3080':750,'GeForce RTX 3070':650,'GeForce RTX 3060':550,'GeForce RTX 3050':550,
 'GeForce RTX 2080 Ti':650,'GeForce RTX 2080 SUPER':650,'GeForce RTX 2080':650,'GeForce RTX 2070 SUPER':650,'GeForce RTX 2070':550,'GeForce RTX 2060 SUPER':550,'GeForce RTX 2060':550,'GeForce GTX 1660':450,'GeForce GTX 1070 Ti':500,'GeForce GTX 1050':300,
 'Radeon RX 9070 XT':750,'Radeon RX 9070':650,'Radeon RX 9070 GRE':650,'Radeon RX 9060 XT 16 GB':650,'Radeon RX 9060 XT 8 GB':650,'Radeon RX 7900 XTX':800,'Radeon RX 7900 XT':750,'Radeon RX 7900 GRE':700,'Radeon RX 7800 XT':700,'Radeon RX 7700 XT':700,'Radeon RX 7600 XT':600,'Radeon RX 7600':550,
 'Radeon RX 6800 XT':750,'Radeon RX 6800':650,'Radeon RX 6750 XT':650,'Radeon RX 6750 GRE 12 GB':650,'Radeon RX 6750 GRE 10 GB':600,'Radeon RX 6700 XT':650,'Radeon RX 6700':600,'Radeon RX 6650 XT':500,'Radeon RX 6600 XT':500,
 'Arc B580':600,'Arc B570':600,'Arc A770':600,'Arc A750':600,'Arc A580':550,'Arc A380':350,'Arc A310':300
};
function recommendedGpuPsu(item){if(item.kind!=='gpu')return null;const exact=GPU_PSU_REFERENCE[item.name];if(exact)return `${exact} W (referencia)`;const boardPower=Number(String(item.specs?.TGP||item.specs?.TBP||'').match(/[\d.]+/)?.[0]);if(!boardPower)return 'Consulta la recomendación del fabricante del modelo exacto';const estimate=boardPower<=75?300:boardPower<=130?450:boardPower<=170?500:boardPower<=200?550:boardPower<=230?600:boardPower<=270?650:boardPower<=320?700:boardPower<=360?750:boardPower<=450?850:1000;return `${estimate} W (estimación orientativa)`}
function showSpecs(item){
  const soon=isComingSoon(item);
  const formattedDate=catalogDateLabel(item);
  const launchText=soon
    ?(formattedDate?`Salida prevista ${formattedDate}`:'Fecha de salida aún no anunciada')
    :(formattedDate?`Lanzamiento ${formattedDate}`:'Lanzamiento anunciado');
  $('#dialog-kind').textContent=`${item.brand} · ${item.kind==='cpu'?'CPU':'GPU'}${soon?' · COMING SOON':''}`;
  $('#dialog-title').textContent=item.name;
  $('#dialog-subtitle').textContent=`${item.generation||'Nueva generación'} · ${launchText}`;
  const specs={...(item.specs||{})};
  if(item.kind==='gpu')specs['Fuente recomendada para el sistema']=specs['Fuente recomendada para el sistema']||specs['PSU recomendada']||recommendedGpuPsu(item);
  $('#dialog-specs').innerHTML=Object.entries(specs).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')||'<div><dt>Especificaciones</dt><dd>El fabricante aún no ha publicado los detalles.</dd></div>';
  const reviewText=soon?'Aún no hay suficientes análisis de una versión comercial para resumir su rendimiento. Cuando haya reviews, esta nota se actualizará.':reviewGuide(item);
  $('#dialog-review-note').textContent=reviewText+(item.kind==='gpu'?' La potencia de fuente mostrada es una referencia para el sistema completo; el ensamblador de cada tarjeta puede recomendar un valor distinto.':'');
  const alerts=alertsForItem(item);$('#dialog-review-alerts').classList.toggle('hidden',!alerts.length);$('#dialog-review-alerts').innerHTML=alerts.length?`<h4>Advertencias documentadas en reviews y reportes de usuarios</h4>${alerts.slice(0,5).map(alert=>`<article><p><strong>${esc(alert.warning)}</strong></p><a href="${esc(safeExternalUrl(alert.url)||'#')}" target="_blank" rel="noopener noreferrer">${esc(alert.title)}</a><small>${esc(alert.source||'Fuente externa')} · ${esc(alert.date||'')}</small></article>`).join('')}`:'';
  const modelQuery=encodeURIComponent(`${item.name} review`),communityQuery=encodeURIComponent(`${item.name} review experience`),sources=[];
  if(item.sourceUrl)sources.push(`<a href="${esc(safeExternalUrl(item.sourceUrl))}" target="_blank" rel="noopener noreferrer">Anuncio oficial</a>`);
  sources.push(`<a href="https://www.google.com/search?q=${modelQuery}+site%3Atomshardware.com" target="_blank" rel="noopener noreferrer">Reviews especializadas</a>`,`<a href="https://www.google.com/search?q=${communityQuery}+site%3Areddit.com" target="_blank" rel="noopener noreferrer">Opiniones de usuarios</a>`);
  $('#dialog-review-sources').innerHTML=sources.join('');
  $('#component-dialog').showModal();
}
$('#close-dialog').onclick=()=>$('#component-dialog').close();

async function loadBuilds(){let data=[],error=null;if(previewUserId){const grants=await supabaseClient.from('build_access').select('build_id').eq('user_id',previewUserId);if(grants.error)error=grants.error;else{const ids=(grants.data||[]).map(row=>row.build_id);if(ids.length){const result=await supabaseClient.from('builds').select('id,name,parts,created_at').in('id',ids).order('created_at',{ascending:true});data=result.data;error=result.error}}}else{const result=await supabaseClient.from('builds').select('id,name,parts,created_at').order('created_at',{ascending:true});data=result.data;error=result.error}if(error){$('#no-access').classList.add('hidden');$('#build-list').innerHTML=`<div class="empty-state">No se pudieron cargar los montajes desde Supabase. Comprueba que existe la tabla <code>builds</code> y que sus políticas RLS permiten esta consulta.<br><small>${esc(error.message)}</small></div>`;return}builds=data||[];const availableIds=new Set(builds.map(build=>build.id));expandedBuildIds=new Set([...expandedBuildIds].filter(id=>availableIds.has(id)));const showNoAccess=previewUserId?builds.length===0:!isAdmin&&builds.length===0;$('#no-access').classList.toggle('hidden',!showNoAccess);$('#no-access').textContent=previewUserId?`${previewUsername} aún no tiene acceso a ver ningún montaje.`:'Aún no tienes acceso a ver ningún montaje, contacta con el administrador para que te de acceso';$('#new-build').classList.toggle('hidden',!canManage());$('#builds-subtitle').textContent=previewUserId?`Vista de solo lectura como ${previewUsername}.`:isAdmin?'Tus configuraciones guardadas.':'Montajes compartidos contigo.';$('#build-list').innerHTML=builds.map(b=>buildMarkup(b)).join('');$$('.build-card').forEach(card=>{if(expandedBuildIds.has(card.dataset.id)){card.classList.add('open');card.querySelector('.build-body').classList.remove('hidden');card.querySelectorAll('.cell-input').forEach(fitCell)}});saveUiPreferences();wireBuilds()}
function buildMarkup(build){const parts=build.parts||{};const peripherals=parts['Periféricos'];const total=PARTS.reduce((sum,p)=>sum+priceValue(parts[p]?.price),0)+priceValue(peripherals?.price);const valueCell=(part,field,value,extra='')=>canManage()?`<textarea class="cell-input ${extra}" data-part="${part}" data-field="${field}" rows="1" placeholder="—">${esc(value||'')}</textarea>`:`<span class="cell-value ${extra}">${esc(value||'—')}</span>`;const rowMarkup=(part,item={})=>`<tr><td data-label="Pieza" class="part-cell">${part}</td><td data-label="Modelo">${valueCell(part,'model',item.model)}</td><td data-label="Precio">${valueCell(part,'price',item.price,'price-input')}</td><td data-label="URL"><div class="url-cell">${canManage()?`<a class="url-open ${safeExternalUrl(item.url)?'':'hidden'}" href="${esc(safeExternalUrl(item.url)||'#')}" target="_blank" rel="noopener noreferrer" aria-label="Abrir URL en una pestaña nueva" title="Abrir enlace">↗</a>${valueCell(part,'url',item.url,'url-input')}`:item.url?`<span class="cell-value url-text">${esc(item.url)}</span>${safeExternalUrl(item.url)?`<a class="url-open" href="${esc(safeExternalUrl(item.url))}" target="_blank" rel="noopener noreferrer" aria-label="Abrir URL en una pestaña nueva" title="Abrir enlace">↗</a>`:''}`:'<span class="muted">—</span>'}</div></td><td data-label="Fecha estimada">${valueCell(part,'eta',item.eta,'eta-input')}</td><td data-label="Ha llegado?"><button class="arrival-cell ${item.arrived?'arrived':''}" data-part="${part}" ${canManage()?'':'disabled'}>${item.arrived?'Sí':'No'}</button></td></tr>`;const rows=PARTS.map(part=>rowMarkup(part,parts[part]||{})).join('')+(peripherals?rowMarkup('Periféricos',peripherals):'');return `<article class="build-card" data-id="${build.id}"><div class="build-heading-row">${canManage()?'<button class="name-edit-button" type="button" aria-label="Editar nombre del montaje" title="Editar nombre">✎</button>':''}<button class="build-heading"><span><span class="build-name">${esc(build.name)}</span>${canManage()?`<input class="inline-name hidden" value="${esc(build.name)}" aria-label="Nombre del montaje" readonly>`:''}<small>creado ${new Date(build.created_at).toLocaleDateString('es-ES')}</small></span><span class="chevron">⌄</span></button></div><div class="build-body hidden"><p class="price-total">Precio = <span class="total-value">${fmtPrice(total)}</span></p><div class="build-table-wrap"><table><colgroup><col class="part-column"><col class="model-column"><col class="price-column"><col class="url-column"><col class="eta-column"><col class="arrival-column"></colgroup><thead><tr><th>Pieza</th><th>Modelo</th><th>Precio</th><th>URL</th><th>Fecha de llegada estimada</th><th>Ha llegado?</th></tr></thead><tbody>${rows}</tbody></table></div>${canManage()?`<div class="build-actions">${peripherals?'':'<button class="button secondary add-peripheral">Añadir periférico</button>'}<button class="button ghost delete-build">Eliminar montaje</button></div>`:''}</div></article>`}
function priceValue(value){const n=parseFloat(String(value||'').replace(/[€\s]/g,'').replace(',','.'));return Number.isFinite(n)?n:0}function fmtPrice(n){return new Intl.NumberFormat('es-ES',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n)+'€'}
function fitCell(input){input.style.height='auto';input.style.height=`${Math.max(input.scrollHeight,32)}px`}
function wireBuilds(){$$('.build-heading').forEach(head=>head.onclick=e=>{const nameField=e.target.closest('.inline-name');if(nameField&&!nameField.readOnly)return;const card=head.closest('.build-card');card.classList.toggle('open');card.querySelector('.build-body').classList.toggle('hidden');if(card.classList.contains('open')){expandedBuildIds.add(card.dataset.id);card.querySelectorAll('.cell-input').forEach(fitCell)}else expandedBuildIds.delete(card.dataset.id);saveUiPreferences()});if(!canManage())return;$$('.name-edit-button').forEach(button=>button.onclick=e=>{e.stopPropagation();const card=button.closest('.build-card'),input=card.querySelector('.inline-name');card.querySelector('.build-name').classList.add('hidden');input?.classList.remove('hidden');input?.removeAttribute('readonly');input?.focus();input?.select()});$$('.inline-name').forEach(input=>{input.addEventListener('blur',()=>saveBuildName(input));input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();input.blur()}if(e.key==='Escape'){input.value=builds.find(b=>b.id===input.closest('.build-card').dataset.id)?.name||'';input.blur()}});input.addEventListener('click',e=>e.stopPropagation())});$$('.cell-input').forEach(input=>{fitCell(input);input.addEventListener('input',()=>{fitCell(input);if(input.dataset.field==='url'){const link=input.parentElement.querySelector('.url-open');if(link){const url=safeExternalUrl(input.value);link.href=url||'#';link.classList.toggle('hidden',!url)}}});input.addEventListener('change',()=>saveCell(input))});$$('.arrival-cell').forEach(btn=>btn.onclick=()=>{btn.classList.toggle('arrived');btn.textContent=btn.classList.contains('arrived')?'Sí':'No';saveArrival(btn)});$$('.add-peripheral').forEach(btn=>btn.onclick=()=>addPeripheral(btn.closest('.build-card')));$$('.delete-build').forEach(btn=>btn.onclick=()=>deleteBuild(btn.closest('.build-card').dataset.id))}
async function saveCell(input){const card=input.closest('.build-card');const build=builds.find(b=>b.id===card.dataset.id);build.parts??={};build.parts[input.dataset.part]??={};build.parts[input.dataset.part][input.dataset.field]=input.value;await persistParts(build,card)}
async function saveArrival(btn){const card=btn.closest('.build-card'),build=builds.find(b=>b.id===card.dataset.id);build.parts??={};build.parts[btn.dataset.part]??={};build.parts[btn.dataset.part].arrived=btn.classList.contains('arrived');await persistParts(build,card)}
async function persistParts(build,card){const {error}=await supabaseClient.from('builds').update({parts:build.parts}).eq('id',build.id);if(error){toast('No se pudo guardar el cambio');return}const total=PARTS.reduce((sum,p)=>sum+priceValue(build.parts[p]?.price),0)+priceValue(build.parts['Periféricos']?.price);card.querySelector('.total-value').textContent=fmtPrice(total)}
async function addPeripheral(card){const build=builds.find(b=>b.id===card.dataset.id);build.parts??={};if(build.parts['Periféricos'])return;build.parts['Periféricos']={model:'',price:'',url:'',eta:'',arrived:false};const {error}=await supabaseClient.from('builds').update({parts:build.parts}).eq('id',build.id);if(error){delete build.parts['Periféricos'];toast('No se pudo añadir el periférico');return}const wasOpen=card.classList.contains('open');await loadBuilds();if(wasOpen){const updated=document.querySelector(`.build-card[data-id="${build.id}"]`);updated?.classList.add('open');updated?.querySelector('.build-body').classList.remove('hidden')}}
async function saveBuildName(input){input.setAttribute('readonly','');const card=input.closest('.build-card'),build=builds.find(b=>b.id===card.dataset.id),name=input.value.trim();if(!name||name===build.name){input.value=build.name;input.classList.add('hidden');card.querySelector('.build-name').classList.remove('hidden');return}const {error}=await supabaseClient.from('builds').update({name}).eq('id',build.id);if(error){input.value=build.name;toast('No se pudo cambiar el nombre');input.classList.add('hidden');card.querySelector('.build-name').classList.remove('hidden');return}build.name=name;card.querySelector('.build-name').textContent=name;input.value=name;input.classList.add('hidden');card.querySelector('.build-name').classList.remove('hidden');toast('Nombre actualizado')}
async function deleteBuild(id){if(!confirm('¿Eliminar este montaje?'))return;const {error}=await supabaseClient.from('builds').delete().eq('id',id);if(error){toast('No se pudo eliminar');return}expandedBuildIds.delete(id);saveUiPreferences();toast('Montaje eliminado');await loadBuilds()}
$('#new-build').onclick=()=>{$('#new-build-form').classList.remove('hidden');$('#new-build-name').focus()};$('#cancel-new-build').onclick=()=>$('#new-build-form').classList.add('hidden');$('#new-build-form').onsubmit=async e=>{e.preventDefault();const name=$('#new-build-name').value.trim();const parts=Object.fromEntries(PARTS.map(p=>[p,{model:'',price:'',url:'',eta:'',arrived:false}]));const {error}=await supabaseClient.from('builds').insert({name,parts});if(error){toast('No se pudo crear el montaje');return}e.target.reset();e.target.classList.add('hidden');toast('Montaje creado');await loadBuilds()};

async function loadAccessPanel(){const [{data:users,error:userError},{data:allBuilds,error:buildError},{data:access,error:accessError}]=await Promise.all([supabaseClient.from('profiles').select('id,username').order('username'),supabaseClient.from('builds').select('id,name').order('name'),supabaseClient.from('build_access').select('user_id,build_id')]);if(userError||buildError||accessError){$('#access-list').innerHTML='<p class="muted">No se pudieron cargar los permisos. Revisa el SQL de configuración.</p>';return}profiles=(users||[]).filter(u=>u.id!==session.user.id);accessMap={};(access||[]).forEach(a=>{accessMap[a.user_id]??=new Set();accessMap[a.user_id].add(a.build_id)});$('#access-list').innerHTML=profiles.length?profiles.map(u=>`<div class="access-row"><div class="access-user">${esc(u.username)}<small>${accessMap[u.id]?.size||0} montajes permitidos</small></div><div class="access-checks">${allBuilds.length?allBuilds.map(b=>`<label class="access-check"><input type="checkbox" data-user="${u.id}" data-build="${b.id}" ${accessMap[u.id]?.has(b.id)?'checked':''}>${esc(b.name)}</label>`).join(''):'<span class="muted">Crea un montaje para asignar acceso.</span>'}</div></div>`).join(''):'<p class="muted">No hay otros usuarios registrados. Crea sus cuentas desde Supabase y pulsa Actualizar.</p>';$$('.access-check input').forEach(input=>input.onchange=()=>setAccess(input))}
async function setAccess(input){const values={user_id:input.dataset.user,build_id:input.dataset.build};const result=input.checked?await supabaseClient.from('build_access').upsert(values,{onConflict:'user_id,build_id'}):await supabaseClient.from('build_access').delete().match(values);if(result.error){input.checked=!input.checked;toast('No se pudo actualizar el acceso');return}await loadAccessPanel();toast('Permiso actualizado')}
$('#refresh-users').onclick=loadAccessPanel;

supabaseClient?.auth.getSession().then(({data})=>{if(data.session){session=data.session;startApp()}});
